import{z as T,x as S,o as E,c as A,q as o,j as i,D as s,d as t,s as n,S as r,b as e}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"TCP 状态机","description":"","frontmatter":{"title":"TCP 状态机","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tcp-state-machine.md","filePath":"cs/tcp-state-machine.md","lastUpdated":1791413859000}'),I={name:"cs/tcp-state-machine.md"};function p(d,a,c,C,B,D){const l=S("Mermaid");return E(),A("div",null,[a[2]||(a[2]=o('<h1 id="tcp-状态机" tabindex="-1">TCP 状态机 <a class="header-anchor" href="#tcp-状态机" aria-label="Permalink to &quot;TCP 状态机&quot;">​</a></h1><div class="epigraph"><p>连接是状态机：LISTEN、握手三态、ESTABLISHED、四次挥手各态；错误的迁移比错一个 cwnd 更容易把套接字卡死。</p><footer>—— 据 RFC 9293 第 3.3 节；Stevens, TCP/IP Illustrated 状态图整理</footer></div><p>主干<a href="/cs/tcp-handshake">三次握手</a> 与 <a href="/cs/tcp-time-wait">TIME_WAIT</a> 已拆过。<a href="/cs/mss-clamping">上一课</a> 发生在 SYN 上。缺口是<strong>整图</strong>：11 个状态怎么迁，ABORT vs 优雅关。本课不把 SYN cookie 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>应用看 ESTABLISHED 与 close。内核还要 SYN-SENT、SYN-RECEIVED、FIN-WAIT-1/2、CLOSING、CLOSE-WAIT、LAST-ACK、TIME_WAIT。同时打开、同时关闭是边角。RST 从多数态回到 CLOSED。半开：一边已关或崩溃，另一边还 ESTABLISHED——保活后课。窗口缩放只在 SYN 协商，状态错了不能补选项。</p><p>不要把状态机写成拥塞控制；cwnd 是 ESTABLISHED 里的变量。</p><p><span class="marginnote">RFC 9293 图 5。本课不把每条错误迁移画成考试填空，只钉主路径与 TIME_WAIT 理由（已在主干）。</span></p><h3 id="拥塞变量栖在-established" tabindex="-1">拥塞变量栖在 ESTABLISHED <a class="header-anchor" href="#拥塞变量栖在-established" aria-label="Permalink to &quot;拥塞变量栖在 ESTABLISHED&quot;">​</a></h3><p>应用 close 不等于 CLOSED。RST 中止；TIME_WAIT 防旧段。同时打开是规范允许的边角。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画主路径：LISTEN → SYN-RCVD → EST → 主动关 FIN-WAIT → TIME_WAIT。对照 QUIC：连接 ID 迁移后课，状态更少暴露。</p>',11)),(E(),i(r,null,{default:s(()=>[n(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20LI%5B%22LISTEN%22%5D%20--%3E%20SR%5B%22SYN-RECEIVED%22%5D%0A%20%20SR%20--%3E%20ES%5B%22ESTABLISHED%22%5D%0A%20%20ES%20--%3E%20FW%5B%22FIN-WAIT%22%5D%0A%20%20FW%20--%3E%20TW%5B%22TIME_WAIT%22%5D%0A%20%20ES%20--%3E%20RST%5B%22RST%20%E5%88%B0%20CLOSED%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},[t("数字实例："),e("code",null,"netstat"),t(" 里成千上万个 CLOSE-WAIT，几乎都是应用代码忘了调 close——内核在等应用表态，等不到就永远停在这个态，文件描述符随连接一起泄漏。")])],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"SYN 泛洪把 SYN-RCVD 队列填满，下一课 cookies。LACP 与路由变化不改状态机，只改路径。抓包排障：看标志位对状态，比看窗口更先。incast 不改状态，只改拥塞变量。",-1)),a[6]||(a[6]=e("p",null,"同时打开：双方 SYN-SENT → SYN-RCVD → EST，序号交叉，规范允许。",-1)),a[7]||(a[7]=e("p",null,"上面的主路径是服务器视角。拆开拆除过程，主动关闭与被动关闭两侧走的是两组不同状态：",-1)),(E(),i(r,null,{default:s(()=>[n(l,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20ES%5B%22ESTABLISHED%22%5D%20--%3E%20ACT%5B%22%E4%B8%BB%E5%8A%A8%E6%96%B9%E5%8F%91%20FIN%22%5D%0A%20%20ES%20--%3E%20PAS%5B%22%E8%A2%AB%E5%8A%A8%E6%96%B9%E6%94%B6%20FIN%2C%20%E5%9B%9E%20ACK%22%5D%0A%20%20ACT%20--%3E%20FW1%5B%22FIN-WAIT-1%22%5D%0A%20%20FW1%20--%3E%20FW2%5B%22FIN-WAIT-2%2C%20%E7%AD%89%E5%AF%B9%E6%96%B9%20FIN%22%5D%0A%20%20FW2%20--%3E%20TW%5B%22TIME_WAIT%22%5D%0A%20%20PAS%20--%3E%20CW%5B%22CLOSE-WAIT%2C%20%E5%BA%94%E7%94%A8%E4%B8%8D%20close%20%E5%B0%B1%E5%81%9C%E5%9C%A8%E8%BF%99%22%5D%0A%20%20CW%20--%3E%20LA%5B%22LAST-ACK%2C%20%E5%8F%91%E5%87%BA%20FIN%22%5D%0A%20%20LA%20--%3E%20CLS%5B%22CLOSED%22%5D%0A%20%20TW%20--%3E%20CLS%0A"})]),fallback:s(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=o('<p><span class="marginnote">常见误区：容易以为&quot;状态&quot;是两端共享的一个值。实际上每端各持一份：主动关的一端走 FIN-WAIT 与 TIME_WAIT，被动关的一端走 CLOSE-WAIT 与 LAST-ACK，同一时刻两边可以处于完全不同的状态。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 TCP 快速打开的全部 cookie。SYN cookies 是下一课。后课默认：套接字生命周期 = 这份状态机；应用 close 不等于立刻 CLOSED。</p><p>把 TIME_WAIT 当泄漏而全局关，会制造旧段串连接。</p><p><span class="marginnote">直觉类比：优雅关闭像双方道完别再散场；RST 则是把灯直接拉灭——不管对方话有没有说完，两端立刻回 CLOSED，之后迟到的发言自然无人接收。</span></p><p>下一课<a href="/cs/syn-cookies">SYN cookies</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>主路径：听、握、传、挥、TIME_WAIT。</li><li>RST 中止；半开留给保活课。</li><li>拥塞变量栖在 ESTABLISHED。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 9293；Stevens。</li></ul>',8))])}const N=T(I,[["render",p]]);export{m as __pageData,N as default};
